import './schemes.css'
import Scheme from '../Scheme/scheme';
import Modal from '../Modal/Modal';
import Filters from '../filters/Filters';
import SchemeNote from './SchemeNote/SchemeNote';
import { useState, useEffect, useMemo, useRef } from 'react';
import axios from 'axios';
import icons from '../../icons/icons';
import { toast } from 'sonner';
import { Tooltip } from 'react-tooltip';
import SchemeDetailed from '../SchemeDetailed/schemeDetailed';
import CustomInput from '../../subComponents/CustomInput/CustomInput';
import Loader from '../Loader/Loader';

const Schemes = function(props) {
    const url = '/core_api/scheme/'

    const [schemes,setSchemes] = useState(null)
    const [modalActive,setModalActive] = useState(false)
    const [action,setAction] = useState('')
    const [deletionApprove,setDeletionApprove] = useState(null)
    const [schemeId,setSchemeId] = useState(null)
    const [currentScheme,setCurrentScheme] = useState(null)
    const [filterTitle,setFilterTitle] = useState('')

    const clearCurrentScheme = function() {
        localStorage.removeItem('currentScheme')
        setCurrentScheme(null)
    }

    const confirmDeletion = async function(state) {
        if (state === true) {
            let url = `/core_api/scheme/${schemeId}/`
            let schemeName = schemes.find(item => item.id === schemeId).title

            function updateSchemes(id) {
                setSchemes(schemes => schemes.filter(item => item.id !== id))
                toast.success(
                    <div className='toast-message--success'>{icons.success} Схема {schemeName} была успешно удалена!</div>,
                    {duration:5000,position:'bottom-left'}
                )
            }

            function deleteScheme() {
                axiosInstance.delete(url)
                    .then(data => updateSchemes(schemeId))
                    .catch(e => console.log(e))
            }

            deleteScheme()
            setAction('')
            schemeId == currentScheme ? clearCurrentScheme() : setCurrentScheme(currentScheme)
            setSchemeId(null)
        }
        else {
            setAction('')
            setSchemeId(null)
        }
    }

    const removeScheme = async function(id) {
        setSchemeId(id)
        setAction('deleteScheme')
        setModalActive(true)
    }

    const editScheme = async function(id) {
        setSchemeId(id)
        setAction('editScheme')
        setModalActive(true)
    }

    const editSchemeName = async function(title) {
        let data = {
            title:title
        }

        axiosInstance.put(`/core_api/scheme/${schemeId}/`,data)
                .then(data => {
                    let subSchemes = schemes
                    subSchemes.find(item => item.id === schemeId).title = title
                    setSchemes(subSchemes)

                    toast.success(
                        <div className='toast-message--success'>{icons.success} Название схемы было успешно изменено!</div>,
                        {duration:5000,position:'bottom-left'}
                    )

                    setAction('')
                })
                .catch(e => console.log(e))
    }

    const axiosInstance = axios.create({
        headers: {
          'Content-Type': 'application/json',
          'Authorization':`Token ${localStorage.getItem('authToken')}`
        }
    })

    useEffect(() => {
        async function fetchData() {
            await axiosInstance.get(url)
                .then(data => setSchemes(data.data))
                .catch(e => console.log(e))

            localStorage.getItem('currentScheme') ? setCurrentScheme(Number(localStorage.getItem('currentScheme'))) : setCurrentScheme(null)
        }

        fetchData()
    }, [])

    
    function parseData(data) {
        return data.map((scheme) => (<Scheme id={scheme.id} author={scheme.creator} name={scheme.title} removeScheme={removeScheme}/>))
    }

    const cachedData = useMemo(() => {
        if (!schemes) return null
        return parseData(schemes)
    }, [schemes])

    const createNewScheme = function() {
        setAction('addScheme')
        setModalActive(true)
    }

    const updateSchemes = function(id,title,creator) {
        setSchemes([...schemes,{id:id,title:title,creator:creator}])
        toast.success(
            <div className='toast-message--success'>{icons.success} Схема {title} была успешно создана!</div>,
            {duration:5000,position:'bottom-left'}
        )
        setAction('')
        setCurrentScheme(id)
    }

    const filterBySchemeTitle = function(data) {
        if (filterTitle === '') {
            return data
        }
        else {
            let filteredData = data
            filteredData = filteredData.filter(item => item.title.toLowerCase().includes(filterTitle))
            return filteredData
        }
    }

    return(
        <div className={!props.navbarHidden ? 'schemes' : 'schemes schemes--blured'}>
            {/* <Filters /> */}
            <div className='schemes__list'>
                <div className='schemes__list__title'>
                    Список схем
                    <Tooltip id='addscheme' style={{backgroundColor:'rgb(0,48,143)',color:'white',fontSize:'1.75rem',zIndex:1000}} />
                    <div className='schemes__list__title__add-new' data-tooltip-id='addscheme' data-tooltip-content={'Создать схему'} data-tooltip-place='top' onClick={createNewScheme}>{icons.plus}</div>
                </div>
                <div className='schemes__list__filter'>
                    <CustomInput 
                        type='text' 
                        label='Поиск схемы' 
                        substyle={{fontSize:'1.5rem'}}
                        labelstyle={{fontSize:'1.2rem',top:'-0.6rem'}}
                        onchange={(e) => setFilterTitle(e.target.value.toLowerCase())}
                    />
                </div>
                <div className='schemes__list__body'>
                    {schemes ? filterBySchemeTitle(schemes).map(item => 
                        <SchemeNote 
                            id={item.id} 
                            title={item.title} 
                            isCurrent={item.id === currentScheme} 
                            setCurrent={setCurrentScheme} 
                            onDelete={removeScheme}
                            onEdit={editScheme}
                        />
                    ) : <Loader />}
                </div>
            </div>
            <div className='schemes__current'>
                {schemes && currentScheme ? <SchemeDetailed id={currentScheme} name={schemes.find(item => item.id === currentScheme).title} status={'editing'} /> :
                 <div className='schemes__current__placeholder'>
                    {'[ Выберите схему из списка ]'}
                 </div> 
                }
            </div>
            <Modal
                active={modalActive}
                setActive={setModalActive}
                action={action}
                axiosInstance={axiosInstance}
                getResult={action === 'addScheme' ? updateSchemes : action === 'editScheme' ? editSchemeName :  confirmDeletion}
            />
        </div>
    );
}

export default Schemes;