import './racks.css'
import { useParams, useNavigate } from 'react-router-dom';
import Rack from '../Rack/rack';
import axios from 'axios';
import { useState, useEffect } from 'react';
import icons from '../../icons/icons';
import { toast } from 'sonner';
import Modal from '../Modal/Modal';
import CustomInput from '../../subComponents/CustomInput/CustomInput';
import CustomSelect from '../../subComponents/CustomSelect/CustomSelect';
import Loader from '../Loader/Loader';

const Racks = function(props) {
    const {id,status} = useParams()
    const navigate = useNavigate()

    const goBack = () => navigate(-1)

    const [modalActive,setModalActive] = useState(false)
    const [action,setAction] = useState('')
    const [rackId,setRackId] = useState(null)
    const [racks,setRacks] = useState(null)
    const [filterTitle,setFilterTitle] = useState('')
    const [filterUnits,setFilterUnits] = useState('Любое')
    const [filterPower,setFilterPower] = useState('Любая')

    const url = '/core_api/server_rack/'

    const axiosInstance = axios.create({
        headers: {
          'Content-Type': 'application/json',
          'Authorization':`Token ${localStorage.getItem('authToken')}`
        }
    })

    useEffect(() => {
        axiosInstance.get(url,{params:{filter_room_id:id}})
            .then(data => setRacks(data.data))
            .catch(e => console.log(e))
    }, [])

    const showModal = function() {
        setModalActive(true)
        setAction('addRack')
    }

    const addRack = async function(title,units,power) {
        if (Number(units) <= 0 || Number(power) <= 0) {
            toast.error(
                <div className='toast-message--error'>{icons.error} Ошибка! Пожалуйста, проверьте правильность введенных данных и попробуйте еще раз. </div>,
                {duration:5000,position:'bottom-left'}
            )

            setAction('')
        }

        else {
            let data = {
                number_of_units:units,
                room_id:id,
                title:title,
                max_power:power
            }
    
            let updateRacks = function(data) {
                setRacks([...racks,{
                    id:data.data.id,
                    title:data.data.title,
                    number_of_units:data.data.number_of_units,
                    max_power:data.data.max_power
                }])
                toast.success(
                    <div className='toast-message--success'>{icons.success} Серверная стойка {data.data.title} была успешно создана!</div>,
                    {duration:5000,position:'bottom-left'}
                )
            }
    
            await axiosInstance.post(url,data)
                .then(data => updateRacks(data))
                .catch(e => console.log(e))

            setAction('')
        }
    }

    const confirmDeletion = function(id) {
        setRackId(id)
        setAction('delRack')
        setModalActive(true)
    }

    const deleteRack = async function(state) {
        if (state === true) {
            let url = `/core_api/server_rack/${rackId}/`
            let rackTitle = racks.find(item => item.id === rackId).title

            let updateRacks = function() {
                setRacks(racks => racks.filter(item => item.id !== rackId))
                setRackId(null)
                setAction('addRack')
                toast.success(
                    <div className='toast-message--success'>{icons.success} Серверная стойка {rackTitle} была успешно удалена!</div>,
                    {duration:5000,position:'bottom-left'}
                )
            }

            await axiosInstance.delete(url)
                .then(data => updateRacks())
                .catch(e => console.log(e))

            setAction('')
        }
        else {
            setRackId(null)
            setAction('')
        }
    }

    const applyFilters = function(data) {
        let filteredData = data

        filterTitle === '' ? 
        filteredData = filteredData : 
        filteredData = filteredData.filter(item => item.title.toLowerCase().includes(filterTitle))

        filterUnits === 'Любое' ?
        filteredData = filteredData : 
        filterUnits === 'По возрастанию' ?
        filteredData = filteredData.sort((a,b) => a.number_of_units - b.number_of_units) : 
        filteredData = filteredData.sort((a,b) => b.number_of_units - a.number_of_units)

        filterPower === 'Любая' ?
        filteredData = filteredData : 
        filterPower === 'По возрастанию' ?
        filteredData = filteredData.sort((a,b) => a.max_power - b.max_power) : 
        filteredData = filteredData.sort((a,b) => b.max_power - a.max_power)

        return filteredData
    }

    return(
        <div className='racks'>
            <p className='racks__header'>Серверные стойки:</p>
            <div className='racks__filter'>
                <CustomInput 
                    type='text' 
                    label='Поиск стойки' 
                    substyle={{fontSize:'1.5rem',padding:'3px'}}
                    labelstyle={{fontSize:'1.2rem',top:'-0.6rem'}}
                    onchange={(e) => setFilterTitle(e.target.value.toLowerCase())}
                />
                <CustomSelect
                    placeholder={'<Кол-во юнитов>'} 
                    label={'Кол-во юнитов'}
                    labelstyle={{fontSize:'1.2rem',top:'-0.6rem'}}
                    subStyle={{fontSize:'1.5rem'}}
                    editable={false}
                    options={['Любое','По возрастанию','По убыванию']} 
                    value={'Любое'}
                    getValue={(value) => {setFilterUnits(value)}}
                />
                <CustomSelect
                    placeholder={'<Макс. мощность>'} 
                    label={'Макс. мощность'}
                    labelstyle={{fontSize:'1.2rem',top:'-0.6rem'}}
                    subStyle={{fontSize:'1.5rem'}}
                    editable={false}
                    options={['Любая','По возрастанию','По убыванию']} 
                    value={'Любая'}
                    getValue={(value) => {setFilterPower(value)}}
                />
            </div>
            <div className='racks__wrapper'>
                <div className="racks__wrapper__add-new" onClick={showModal}>
                    {icons.squarePlus} Добавить
                </div>
                {racks ? applyFilters(racks).map(rack => (
                    <Rack 
                        id={rack.id} 
                        name={rack.title} 
                        length={rack.number_of_units}
                        max_power={rack.max_power}
                        free_power={rack.free_power}
                        free_units={rack.free_units}
                        delRack={confirmDeletion}
                    />
                )) : <Loader />}
            </div>
            <Modal
                active={modalActive}
                setActive={setModalActive}
                action={action}
                getResult={action === 'addRack' ? addRack : deleteRack}
            />
        </div>
    );
}

export default Racks;