import './buildingNode.css'
import icons from '../../icons/icons';
import { Link } from 'react-router-dom';
import { Handle, Position, useReactFlow } from 'reactflow';
import { useState,useEffect } from 'react';
import axios from 'axios';
import { toast } from 'sonner';
 
function BuildingNode({ data }) {
    const axiosInstance = axios.create({
        headers: {
          'Content-Type': 'application/json',
          'Authorization':`Token ${localStorage.getItem('authToken')}`
        }
    })

    const {setNodes} = useReactFlow()
    const {getNodes} = useReactFlow()

    const removeNode = async function() {
        data.toRes({
            id: data.id,
            type:'buildingNode',
            position: { x: null, y: null },
            data: {
                id: data.id,
                name:data.name,
                toRes:data.toRes,
                toEdit:data.toEdit
            }
        })

        let url = `/core_api/building/${Number(data.id)}/`
        let data1 = {
            coord_x:null,
            coord_y:null
        }

        await axiosInstance.put(url,data1)
            .then(data => {
                console.log(data)
                toast.success(
                    <div className='toast-message--success'>{icons.success} Здание {data.name} было убрано из схемы!</div>,
                    {duration:5000,position:'bottom-left'}
                )
            })
            .catch(e => console.log(e))

        setNodes((prevNodes) => prevNodes.filter((node) => node.id != data.id))
    }

    const [showTools,setShowTools] = useState(false)

    useEffect(() => {
        getNodes()
    })

    return (
        <div id={data.id} className='building' title={data.name} onMouseEnter={() => setShowTools(true)} onMouseLeave={() => setShowTools(false)}>
            <Handle style={{width:'1.5rem', height:'1.5rem'}} type="target" position={Position.Left} id='lin' />
            <Handle style={{width:'1.5rem', height:'1.5rem'}} type="source" position={Position.Right} id="rout" />
            {icons.bn.building}
            <p className='building__title'>{data.name}</p>
            { showTools ? <div className='building__delete' onClick={removeNode}>
                <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 448 512"><path fill='red' d="M64 32C28.7 32 0 60.7 0 96V416c0 35.3 28.7 64 64 64H384c35.3 0 64-28.7 64-64V96c0-35.3-28.7-64-64-64H64zm88 200H296c13.3 0 24 10.7 24 24s-10.7 24-24 24H152c-13.3 0-24-10.7-24-24s10.7-24 24-24z"/></svg>
            </div> : ''}
            
            { showTools ? <Link to={`/cabinets/${data.id}/editing`} state={{description:`${data.name}`}}><svg className='building__view' xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512"><path d="M416 208c0 45.9-14.9 88.3-40 122.7L502.6 457.4c12.5 12.5 12.5 32.8 0 45.3s-32.8 12.5-45.3 0L330.7 376c-34.4 25.2-76.8 40-122.7 40C93.1 416 0 322.9 0 208S93.1 0 208 0S416 93.1 416 208zM208 352a144 144 0 1 0 0-288 144 144 0 1 0 0 288z"/></svg></Link> : ''}

            { showTools ? <div className='building__edit' onClick={() => {data.toEdit(Number(data.id))}}>{icons.edit}</div> : ''}
        </div>
    );
}

export default BuildingNode